-- Converts every DateTime column from Postgres timestamp (no tz) to
-- timestamptz. The session/DB timezone is UTC, matching how Prisma
-- already stores these values, so this is a lossless, same-instant
-- reinterpretation -- not a data change. Needed because sqlx decodes
-- Rust's chrono::DateTime<Utc> fields (used everywhere in the Rust
-- backend) as SQL TIMESTAMPTZ, and refuses to decode a TIMESTAMP
-- (no tz) column into that type.

ALTER TABLE "AccessGrant" ALTER COLUMN "grantedAt" TYPE TIMESTAMPTZ USING "grantedAt" AT TIME ZONE 'UTC';
ALTER TABLE "Account" ALTER COLUMN "createdAt" TYPE TIMESTAMPTZ USING "createdAt" AT TIME ZONE 'UTC';
